:root {
  --bg-ticket: #1a1a2e;
  --bg-header: #16213e;
  --bg-sidebar: #0f3460;
  --bg-specs: #0d0d1a;
  --accent-laser: #e94560;
  --accent-glow: #f5a623;
  --accent-green: #2ecc71;
  --text-primary: #eaeaea;
  --text-secondary: #8892a4;
  --text-muted: #555f6e;
  --chip-bg: #243060;
  --chip-border: #3a4a7a;
  --border-line: #2a2a4a;
  --btn-pause-bg: #2a2a4a;
  --btn-done-bg: #2ecc71;
  --btn-done-text: #0a1a0a;
  --progress-track: #2a2a4a;
  --badge-bg: #e94560;
  --priority-bg: #f5a623;
  --priority-text: #1a1a2e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
}

.job-ticket {
  background: var(--bg-ticket);
  border: 1px solid var(--border-line);
  border-radius: 14px;
  width: 500px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.ticket-header {
  background: var(--bg-header);
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 2px solid var(--accent-laser);
}

.studio-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.studio-icon {
  font-size: 22px;
  line-height: 1;
}

.studio-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.studio-name {
  font-size: 13px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: 0.08em;
}

.studio-tagline {
  font-size: 10px;
  color: var(--text-secondary);
  letter-spacing: 0.05em;
}

.job-badge {
  background: var(--badge-bg);
  border-radius: 6px;
  padding: 4px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0px;
}

.badge-label {
  font-size: 9px;
  font-weight: 700;
  color: #fff;
  letter-spacing: 0.1em;
}

.badge-number {
  font-size: 13px;
  font-weight: 800;
  color: #fff;
  letter-spacing: 0.04em;
}

.ticket-body {
  display: flex;
  flex-direction: row;
  gap: 0;
  flex: 1;
}

.job-main {
  flex: 1;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  border-right: 1px solid var(--border-line);
}

.job-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.job-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.priority-tag {
  background: var(--priority-bg);
  color: var(--priority-text);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
  border-radius: 4px;
  padding: 2px 7px;
}

.material-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.mat-chip {
  background: var(--chip-bg);
  border: 1px solid var(--chip-border);
  border-radius: 20px;
  padding: 3px 10px;
  font-size: 11px;
  color: var(--text-primary);
}

.specs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.spec-cell {
  background: var(--bg-specs);
  border: 1px solid var(--border-line);
  border-radius: 8px;
  padding: 7px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.spec-label {
  font-size: 9px;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.spec-value {
  font-size: 16px;
  font-weight: 800;
  color: var(--accent-glow);
  line-height: 1;
}

.spec-unit {
  font-size: 9px;
  font-weight: 500;
  color: var(--text-secondary);
}

.job-sidebar {
  width: 150px;
  background: var(--bg-sidebar);
  padding: 14px 12px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.status-block {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.status-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.status-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-green);
}

.progress-bar {
  width: 100%;
  height: 6px;
  background: var(--progress-track);
  border-radius: 3px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  width: 67%;
  background: var(--accent-green);
  border-radius: 3px;
}

.progress-pct {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  align-self: flex-end;
}

.timeline-block {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.time-row {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.time-label {
  font-size: 9px;
  color: var(--text-muted);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.time-val {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}

.time-val.accent {
  color: var(--accent-laser);
}

.ticket-footer {
  background: var(--bg-header);
  border-top: 1px solid var(--border-line);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.client-row {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.client-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.client-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
}

.footer-actions {
  display: flex;
  gap: 8px;
}

.btn {
  border: none;
  border-radius: 7px;
  padding: 7px 14px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  letter-spacing: 0.02em;
}

.btn-pause {
  background: var(--btn-pause-bg);
  color: var(--text-secondary);
}

.btn-complete {
  background: var(--btn-done-bg);
  color: var(--btn-done-text);
}
